// ============ Unified HR Calendar (spec §12.1) ============
// A first-class feature that CONSUMES events generated by core engines:
// birthdays, anniversaries, tasks, leaves, holidays, payroll dates, document
// expiries, contract expiries, probation completions, loan installments,
// company events — never creates parallel records.

import { db } from "@/lib/db"
import { getSettings } from "./settings"
import { addDays, today, probationEndDate } from "./utils"

export type CalendarEvent = {
  date: string
  kind: string // BIRTHDAY | ANNIVERSARY | TASK | LEAVE | HOLIDAY | PAYROLL | DOC_EXPIRY | CONTRACT_EXPIRY | PROBATION | LOAN_INSTALL | EVENT | REVIEW | ANNOUNCEMENT
  title: string
  detail?: string
  employeeId?: string
  color: string
  status?: string
}

const COLORS: Record<string, string> = {
  BIRTHDAY: "bg-pink-500", ANNIVERSARY: "bg-amber-500", TASK: "bg-emerald-600",
  LEAVE: "bg-orange-500", HOLIDAY: "bg-red-600", PAYROLL: "bg-teal-600",
  DOC_EXPIRY: "bg-rose-500", CONTRACT_EXPIRY: "bg-rose-600", PROBATION: "bg-purple-500",
  LOAN_INSTALL: "bg-cyan-600", EVENT: "bg-indigo-500", REVIEW: "bg-violet-500",
  ANNOUNCEMENT: "bg-slate-500", PENDING_LEAVE: "bg-orange-300",
}

export async function getCalendarEvents(
  vendorId: string,
  month: number,
  year: number,
  employeeScope?: { branchId?: string | null; departmentId?: string | null; selfEmployeeId?: string | null }
): Promise<CalendarEvent[]> {
  const events: CalendarEvent[] = []
  const monthPrefix = `${year}-${String(month).padStart(2, "0")}`
  const start = `${monthPrefix}-01`
  const end = `${monthPrefix}-${String(new Date(year, month, 0).getDate()).padStart(2, "0")}`
  const settings = await getSettings(vendorId)

  const empFilter: any = { vendorId, status: { in: ["ACTIVE", "PROBATION", "ON_LEAVE", "SUSPENDED"] } }
  if (employeeScope?.branchId) empFilter.branchId = employeeScope.branchId
  if (employeeScope?.departmentId) empFilter.departmentId = employeeScope.departmentId

  const employees = await db.employee.findMany({ where: empFilter })
  const empMap = new Map(employees.map((e) => [e.id, e]))
  // COM-03 (R5) — an EMPLOYEE viewer sees sensitive per-person events ONLY for
  // themselves (colleagues' loan installments, leave days, contract and
  // document expiries, probation dates and task titles are theirs, not the
  // tenant's). Company-culture events (birthdays/anniversaries), holidays,
  // payroll dates, company events and review cycles stay company-wide.
  const SELF_ONLY_KINDS = new Set(["LEAVE", "PENDING_LEAVE", "LOAN_INSTALL", "CONTRACT_EXPIRY", "DOC_EXPIRY", "PROBATION", "TASK"])
  const selfId = employeeScope?.selfEmployeeId || null
  const keep = (e: CalendarEvent) => !selfId || !SELF_ONLY_KINDS.has(e.kind) || e.employeeId === selfId

  // Birthdays & anniversaries (recurring: match month-day)
  for (const e of employees) {
    if (e.dob && e.dob.slice(5, 7) === String(month).padStart(2, "0")) {
      events.push({
        date: `${monthPrefix}-${e.dob.slice(8, 10)}`, kind: "BIRTHDAY",
        title: `🎂 ${e.fullName}`, detail: "Birthday", employeeId: e.id, color: COLORS.BIRTHDAY,
      })
    }
    if (e.joiningDate && e.joiningDate.slice(0, 4) <= String(year) && e.joiningDate.slice(5, 7) === String(month).padStart(2, "0")) {
      const years = year - Number(e.joiningDate.slice(0, 4))
      events.push({
        date: `${monthPrefix}-${e.joiningDate.slice(8, 10)}`, kind: "ANNIVERSARY",
        title: `🎉 ${e.fullName}`, detail: years > 0 ? `${years} year${years > 1 ? "s" : ""} of service` : "Joined this month",
        employeeId: e.id, color: COLORS.ANNIVERSARY,
      })
    }
    // Probation completion.
    // EMP-08 (R7) — CALENDAR-month math (the old joining + months×30 drifted
    // up to two weeks; a Nov 30 joiner's 3-month probation ended "Mar 1").
    const endProbation = probationEndDate(e.joiningDate, e.probationMonths, e.confirmationDate)
    if (e.joiningDate && e.status === "PROBATION" && endProbation && endProbation >= start && endProbation <= end) {
      events.push({ date: endProbation, kind: "PROBATION", title: `Probation completion — ${e.fullName}`, employeeId: e.id, color: COLORS.PROBATION })
    }
    // Contract expiry
    if (e.contractEnd && e.contractEnd >= start && e.contractEnd <= end) {
      events.push({ date: e.contractEnd, kind: "CONTRACT_EXPIRY", title: `Contract expiry — ${e.fullName}`, employeeId: e.id, color: COLORS.CONTRACT_EXPIRY })
    }
  }

  // Holidays.
  // LVE-121 (R6) — branch scope honored: branch-specific holidays (branchId
  // set) only appear for that branch's viewers; null-branch holidays are
  // company-wide. A manager scope filters to their branch.
  const holidayWhere: any = { vendorId, date: { gte: start, lte: end } }
  if (employeeScope?.branchId) holidayWhere.OR = [{ branchId: null }, { branchId: employeeScope.branchId }]
  const holidays = await db.holiday.findMany({ where: holidayWhere })
  for (const h of holidays) {
    events.push({ date: h.date, kind: "HOLIDAY", title: h.name, detail: h.type, color: COLORS.HOLIDAY })
  }

  // Approved & pending leave.
  // COM-06 (R6) — the leave-type lookup is batched: ONE query for all types
  // (the old code ran one findUnique per leave row — N+1 at tenant scale).
  const [leaves, leaveTypesAll] = await Promise.all([
    db.leaveRequest.findMany({
      where: { vendorId, fromDate: { lte: end }, toDate: { gte: start }, status: { in: ["PENDING", "APPROVED"] } },
    }),
    db.leaveType.findMany({ where: { vendorId } }),
  ])
  const typeById = new Map(leaveTypesAll.map((t) => [t.id, t]))
  for (const l of leaves) {
    const emp = empMap.get(l.employeeId)
    const type = typeById.get(l.leaveTypeId)
    if (!emp) continue
    let d = l.fromDate > start ? l.fromDate : start
    const lastDay = l.toDate < end ? l.toDate : end
    while (d <= lastDay) {
      events.push({
        date: d, kind: l.status === "PENDING" ? "PENDING_LEAVE" : "LEAVE",
        title: `${emp.fullName} — ${type?.name || "Leave"} (${l.status.toLowerCase()})`,
        detail: `${l.days} day(s)`, employeeId: emp.id,
        color: l.status === "PENDING" ? COLORS.PENDING_LEAVE : COLORS.LEAVE,
      })
      d = addDays(d, 1)
    }
  }

  // Tasks (due dates)
  const tasks = await db.task.findMany({
    where: { vendorId, dueDate: { gte: start, lte: end }, status: { in: ["TODO", "IN_PROGRESS", "ON_HOLD"] } },
  })
  for (const t of tasks) {
    const emp = empMap.get(t.assigneeId)
    events.push({
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- audited TODO(H-20 paydown): convert to an explicit null check
      date: t.dueDate!, kind: "TASK", title: `Task: ${t.title}`,
      detail: `${emp?.fullName || "—"} · ${t.priority.toLowerCase()} · ${t.progress}%`, employeeId: t.assigneeId, color: COLORS.TASK,
    })
  }

  // Payroll dates (from settings — processing & payment)
  const daysInMonth = new Date(year, month, 0).getDate()
  const procDay = Math.min(settings.payroll.processingDay, daysInMonth)
  const payDay = Math.min(settings.payroll.paymentDay, daysInMonth)
  events.push({
    date: `${monthPrefix}-${String(procDay).padStart(2, "0")}`, kind: "PAYROLL",
    title: "Payroll Processing Date", detail: "Automated payroll run trigger", color: COLORS.PAYROLL,
  })
  events.push({
    date: `${monthPrefix}-${String(payDay).padStart(2, "0")}`, kind: "PAYROLL",
    title: "Salary Payment Date", detail: "Salary disbursement", color: COLORS.PAYROLL,
  })

  // AIT/tax deadline (15th of following month — BD withholding deposit convention)
  events.push({
    date: `${monthPrefix}-15`, kind: "PAYROLL", title: "AIT/Tax Deposit Deadline",
    detail: "Deposit withheld tax for previous month", color: COLORS.PAYROLL,
  })

  // Document expiry (NID/passport etc.)
  const docExpiryWindow = settings.notification.documentExpiryDays
  const horizon = addDays(end, docExpiryWindow)
  const docs = await db.employeeDocument.findMany({
    where: { vendorId, expiryDate: { not: null, gte: today(), lte: horizon } },
  })
  for (const doc of docs) {
    const emp = empMap.get(doc.employeeId)
    if (!emp || !doc.expiryDate) continue
    events.push({
      date: doc.expiryDate, kind: "DOC_EXPIRY", title: `${doc.docType} expiry — ${emp.fullName}`,
      detail: doc.title, employeeId: emp.id, color: COLORS.DOC_EXPIRY,
    })
  }

  // Loan installments due.
  // LVE-121 (R6) — one batched query over the window's active loans (the old
  // code ran one installments query per loan — N+1 at book scale).
  const loans = await db.loan.findMany({ where: { vendorId, status: "ACTIVE" } })
  const loanIds = loans.map((l) => l.id)
  const installments = loanIds.length
    ? await db.loanInstallment.findMany({ where: { vendorId, loanId: { in: loanIds }, dueDate: { gte: start, lte: end }, status: { in: ["PENDING", "OVERDUE", "PARTIAL"] } } })
    : []
  const instByLoan = new Map<string, typeof installments>()
  for (const i of installments) {
    const list = instByLoan.get(i.loanId) || []
    list.push(i)
    instByLoan.set(i.loanId, list)
  }
  for (const loan of loans) {
    const emp = empMap.get(loan.employeeId)
    if (!emp) continue
    for (const i of instByLoan.get(loan.id) || []) {
      events.push({
        date: i.dueDate, kind: "LOAN_INSTALL", title: `Loan installment — ${emp.fullName}`,
        detail: `৳${i.amount.toFixed(0)} (installment #${i.no})`, employeeId: emp.id, color: COLORS.LOAN_INSTALL,
      })
    }
  }

  // Company events & meetings
  const evts = await db.companyEvent.findMany({ where: { vendorId, date: { gte: start, lte: end } } })
  for (const ev of evts) {
    events.push({ date: ev.date, kind: "EVENT", title: ev.title, detail: `${ev.type.replace("_", " ")}${ev.time ? " · " + ev.time : ""}`, color: COLORS.EVENT })
  }

  // Performance review cycles
  const cycles = await db.reviewCycle.findMany({ where: { vendorId, status: "ACTIVE", endDate: { gte: start, lte: end } } })
  for (const cy of cycles) {
    events.push({ date: cy.endDate, kind: "REVIEW", title: `Review cycle ends — ${cy.name}`, color: COLORS.REVIEW })
  }

  events.sort((a, b) => a.date.localeCompare(b.date))
  return events.filter(keep)
}
